update content_bodies set title = '[Hiroshima Tourism] 15 Must-Visit Tourist Spots in Hiroshima and Miyajima', description = 'Please use this as a reference for your trip or sightseeing in Hiroshima Prefecture.
Hiroshima''s representative tourist destination, Miyajima, also known as Itsukushima, is a registered World Heritage site. Miyajima is a ''sacred island'' that has been worshipped since ancient times. Many people seem to want to visit at least once, and a large number of tourists from around the world come to see it. This time, we will guide you through 15 recommended tourist spots in Miyajima.
