This channel is produced based on [official websites and various media information], but regarding images, we quote them without altering the photos, and under the advice of a lawyer, we do not reproduce or adapt copyrighted works in the video. Of course, we are committed to ensuring that we do not inconvenience the image authors and to delivering valuable travel information to our viewers. However, if any copyright holders wish to have their images removed from the video due to any inconvenience, we would appreciate it if you could contact us at the address below. We will respond promptly.

