update content_bodies set title = '【ドローン映像】大桑城跡 | 「戦国のメインステージ岐阜」', description = '大桑城は、室町時代から戦国時代にかけて権勢を誇った、美濃国の守護土岐氏の山城です。天文4（1535）年に発生した長良川の大洪水により、枝広（現在の岐阜市長良公園）にあった守護所は大きな被害を受けました。これを受けて土岐氏は、大桑に守護所を移し、城と城下町を整備したとされています。天文12（1543）年、勢力を増していた斎藤道三との間に大きな戦いが起こり、大桑城は落城したと考えられています。

▽アクセスやお問い合わせはこちら
大桑城跡（古城山） | 岐阜県観光公式サイト「岐阜の旅ガイド」
https://www.kankou-gifu.jp/spot/detail_5944.html' where id = '7EVTfDWaJTnZrQqVDxki-';
update content_bodies set title = '[Drone Footage] Okuwa Castle Ruins | ''The Main Stage of the Sengoku Period in Gifu''', description = 'Okuwa Castle is a mountain castle of the Toki clan, who held power in Mino Province from the Muromachi period to the Sengoku period. In 1535, a major flood of the Nagara River caused significant damage to the guardian''s base located in Ebihiro (now Nagara Park in Gifu City). In response, the Toki clan moved their base to Okuwa and is said to have developed the castle and the castle town. In 1543, a major battle occurred between the Toki clan and the increasingly powerful Saito Dosan, leading to the fall of Okuwa Castle.

▽ For access and inquiries, click here
Okuwa Castle Ruins (Kojoyama) | Gifu Prefectural Official Tourism Site ''Gifu Travel Guide''
https://www.kankou-gifu.jp/spot/detail_5944.html' where id = 'KQRqFqT57Nw380Ve3HoJq';
update content_bodies set title = '【ドローン映像】小島城跡 | 「戦国のメインステージ岐阜」', description = '小島城跡は姉小路氏三家の一家・小島氏の居城です。高原郷と小島郷を結ぶ神原峠の峠道が脇を通る交通の要衝に位置し、高原郷からの敵の侵入を睨んでいます。姉小路氏城跡は古川城跡、小島城跡、野口城跡、向小島城跡、小鷹利城跡という5つの城跡の総称で、飛騨市古川町などにあります。令和6年2月21日、その歴史的価値が評価されて国史跡に指定されました。

▽アクセスやお問い合わせはこちら
小島城跡 | 岐阜県観光公式サイト「岐阜の旅ガイド」
https://www.kankou-gifu.jp/spot/detail_7364.html' where id = 'qSQnWzCI9jfx5hIkaIyzC';
update content_bodies set title = '[Drone Footage] Kojima Castle Ruins | ''The Main Stage of the Warring States in Gifu''', description = 'The Kojima Castle Ruins are the residence of the Kojima clan, one of the three branches of the Anekoji clan. It is located at a strategic point along the mountain pass connecting Takahara and Kojima, overseeing the potential invasion of enemies from Takahara. The Anekoji clan castle ruins refer to a collective of five castle ruins: Furukawa Castle, Kojima Castle, Noguchi Castle, Mukokojima Castle, and Kotakatori Castle, located in places like Furukawa Town in Hida City. On February 21, 2024, its historical value was recognized, and it was designated as a national historic site.

▽ For access and inquiries, click here
Kojima Castle Ruins | Gifu Prefectural Official Tourism Site ''Gifu Travel Guide''
https://www.kankou-gifu.jp/spot/detail_7364.html' where id = 'KfC_mi9uag29FkPpdGz31';
update content_bodies set title = '【ドローン映像】大垣城 | 「戦国のメインステージ岐阜」', description = '大垣城は、美濃守護・土岐一族の宮川吉左衛門尉安定により、天文4年（1535年）に創建されたと伝えられています。江戸時代の大垣城は、城郭絵図によると水堀を幾重にもめぐらせた大変規模の大きな城郭でした。関ケ原の戦いでは、西軍・石田三成の本拠地となりました。その後、戸田氏が入城し、大垣藩十万石を明治時代まで治めました。

▽アクセスやお問い合わせはこちら
大垣城 | 岐阜県観光公式サイト「岐阜の旅ガイド」
https://www.kankou-gifu.jp/spot/detail_894.html' where id = 'Q-aOuTArq1ify_AgWyWdi';
update content_bodies set title = '[Drone Footage] Ogaki Castle | ''The Main Stage of the Warring States in Gifu''', description = 'Ogaki Castle is said to have been founded in the 4th year of Tenbun (1535) by Miyakawa Yoshizaemon-no-Suke Yasutaka of the Toki clan, the guardians of Mino. According to Edo period castle maps, Ogaki Castle was a large fortress surrounded by multiple moats. During the Battle of Sekigahara, it became the base of the Western Army led by Ishida Mitsunari. Later, the Toda clan took control of the castle and governed the Ogaki Domain of 100,000 koku until the Meiji period.

▽ For access and inquiries, click here
Ogaki Castle | Gifu Prefectural Official Tourism Site ''Gifu Travel Guide''
