update content_bodies set title = '【ドローン映像】岐阜城 | 「戦国のメインステージ岐阜」', description = '金華山頂にはじめて砦を築いたのは、鎌倉幕府に仕えた二階堂山城守行政と伝えられています。戦国時代には、斎藤道三公の居城でもあったところです。特に岐阜城の名を天下に示したのは、永禄10年（1567年）8月、織田信長公がこの城を攻略し、地名も「井口」を「岐阜」と改称し、天下統一の本拠地としてからでした。

▽アクセスやお問い合わせはこちら
岐阜城 | 岐阜県観光公式サイト「岐阜の旅ガイド」
https://www.kankou-gifu.jp/spot/detail_912.html' where id = 'VoMNK7AbTYVRKdXeL2o0U';
update content_bodies set title = '[Drone Footage] Gifu Castle | ''The Main Stage of the Warring States Period in Gifu''', description = 'It is said that the first fort was built on the summit of Kinka Mountain by Nikaido Yamashiro no Kami Yoshinari, who served the Kamakura Shogunate. During the Warring States period, it was also the residence of Saito Dosan. Particularly, the name of Gifu Castle was made known throughout the land when, in the 10th year of Eiroku (1567), Oda Nobunaga conquered this castle, renaming the place from ''Iguchi'' to ''Gifu'' and establishing it as the base for his unification of the country.

▽ For access and inquiries, click here
Gifu Castle | Gifu Prefectural Official Tourism Site ''Gifu Travel Guide''
https://www.kankou-gifu.jp/spot/detail_912.html' where id = 'Z14UaClfB6eWc6YtK3nfd';
update content_bodies set title = '【ドローン映像】岩村城跡 | 「戦国のメインステージ岐阜」', description = '岩村城は、奈良県の高取城、岡山県の松山城と並び、日本三大山城の一つに数えられる名城で、日本100名城にも選定されています。城は江戸諸藩の府城の中でも最も高い所（標高717m）に築かれ、高低差180mの険しい地形を巧みに利用した要害堅固な山城です。霧の湧き易い気象も城造りに活かされ、別名「霧ヶ城」とも呼ばれています。

▽アクセスやお問い合わせはこちら
岩村城跡 | 岐阜県観光公式サイト「岐阜の旅ガイド」
https://www.kankou-gifu.jp/spot/detail_1344.html' where id = 'xQfSFIzVZCAhzHpGlcAQP';
update content_bodies set title = '[Drone Footage] Iwamura Castle Ruins | ''The Main Stage of the Sengoku Period in Gifu''', description = 'Iwamura Castle is considered one of Japan''s three great mountain castles, alongside Takatori Castle in Nara Prefecture and Matsuyama Castle in Okayama Prefecture, and it has also been selected as one of Japan''s 100 Famous Castles. The castle was built at the highest elevation (717m) among the various Edo period feudal lords'' castles, utilizing the steep terrain with a height difference of 180m to create a formidable mountain fortress. The fog-prone weather has also been utilized in the castle''s construction, earning it the nickname ''Kiri no Shiro'' (Castle of Fog). 

▽ For access and inquiries, click here
Iwamura Castle Ruins | Gifu Prefecture Official Tourism Site ''Gifu Travel Guide''
https://www.kankou-gifu.jp/spot/detail_1344.html' where id = 'FXL36Y4JeI9VYgMw8OvDb';
update content_bodies set title = '【ドローン映像】菩提山城跡 | 「戦国のメインステージ岐阜」', description = '永禄元年（1558年）、この地で権力を持っていた岩手氏を竹中重元と息子・重治（半兵衛）が攻め落とし、翌年菩提山に城を築いたとされています。
菩提山城は、竪堀や高低差の大きい堀切が複雑に組み合わさった大規模な山城です。塁はすべて土塁であり、石塁が見られないのが特徴で、最も完成型に近い土塁による城郭といわれています。

▽アクセスやお問い合わせはこちら
菩提山城跡ハイキングコース | 岐阜県観光公式サイト「岐阜の旅ガイド」
https://www.kankou-gifu.jp/spot/detail_5488.html' where id = 'cgB3Lt7KYSynwd6hS8jEx';
update content_bodies set title = '[Drone Footage] Bodaisan Castle Ruins | ''The Main Stage of the Warring States in Gifu''', description = 'In the first year of Eiroku (1558), it is said that Takeuchi Shigemoto and his son Shigeharu (Hanbei) attacked the Iwate clan, who held power in this area, and built a castle on Bodaisan the following year.
Bodaisan Castle is a large mountain castle with a complex combination of vertical moats and significant elevation differences. The ramparts are all earthen mounds, and it is characterized by the absence of stone walls, being regarded as the most complete example of an earthen mound castle.

▽ For access and inquiries, click here
Bodaisan Castle Ruins Hiking Course | Gifu Prefectural Official Tourism Site ''Gifu Travel Guide''
https://www.kankou-gifu.jp/spot/detail_5488.html' where id = 'F7ET_qIJBUhod9qHHlw3X';
update content_bodies set title = '【ドローン映像】苗木城跡 | 「戦国のメインステージ岐阜」', description = '苗木城は、苗木遠山氏により戦国時代（1526年頃）に築城されました。天然の巨石を利用して構築された石垣は、全国でも大変珍しいものです。大矢倉などでは、岩を抱き抱えるように積まれた石垣を見ることができます。
また、年代によって異なる技法で石垣が積まれているのも特徴の一つで、続日本100名城にも選ばれています。

