update content_bodies set title = '[Drone Footage] Naegi Castle Ruins | ''The Main Stage of the Sengoku Period in Gifu''', description = 'Naegi Castle was built by the Naegi Toyama clan during the Sengoku period (around 1526). The stone walls constructed using natural giant stones are quite rare in the country. At places like Oyakura, you can see stone walls stacked in a way that embraces the rocks.
Additionally, one of the features is that the stone walls are built using different techniques depending on the era, and it has also been selected as one of the 100 Famous Castles of Japan.

