update content_bodies set title = '【ドローン映像】美濃金山城跡 | 「戦国のメインステージ岐阜」', description = '市内屈指の展望を誇る可児市の古城山山頂に、道三の養子である斎藤正義によって1537年(天文6年)に烏峰城が築城されたと伝えられています。その後、森可成が信長から城を賜り城主となり、「金山城」に改称され、およそ35年にわたり森氏の居城となりました。
美濃金山城跡は、約400年前の石垣が当時の姿のまま残されており、戦国時代の息づかいを肌で感じることができる貴重な城跡で、平成25年に国史跡に指定され、続日本100名城にも選ばれています。

▽アクセスやお問い合わせはこちら
国史跡 美濃金山城跡 | 岐阜県観光公式サイト「岐阜の旅ガイド」
https://www.kankou-gifu.jp/spot/detail_4238.html' where id = '5wAGix-hDLXWUrdFI6-mU';
update content_bodies set title = '[Drone Footage] Mino Kanayama Castle Ruins | ''The Main Stage of the Warring States in Gifu''', description = 'It is said that Kōfū Castle was built in 1537 (Tembun 6) on the summit of Kōjōyama in Kani City, which boasts one of the best views in the city, by Saitō Masayoshi, the adopted son of Dosan. Later, Mori Kanetaka received the castle from Nobunaga and became the lord, renaming it ''Kanayama Castle,'' which served as the residence of the Mori clan for about 35 years.

The Mino Kanayama Castle Ruins preserve stone walls from about 400 years ago in their original form, making it a valuable site where one can feel the breath of the Warring States period. In 2013, it was designated as a national historic site and selected as one of the Continued 100 Famous Castles of Japan.

▽ For access and inquiries, click here
National Historic Site Mino Kanayama Castle Ruins | Gifu Prefectural Official Tourism Site ''Gifu Travel Guide''
https://www.kankou-gifu.jp/spot/detail_4238.html' where id = '4FRgDRuo6HTsXcUHnj2pR';
update content_bodies set title = '「Perfect G」【馬籠宿編】　貴方もこれで、岐阜マニア！', description = '岐阜県は、世界遺産白川郷や下呂温泉、飛騨高山、長良川の鵜飼など、多くの観光地があり、毎年とてもたくさんのお客様にお越しいただいています。
そんな岐阜県をもっと深く知ってほしい！
「Perfect G」は、そんな岐阜県の魅力をユニークな切り口で取り上げます。

馬籠宿編　是非ご覧ください。

岐阜県の観光情報は、岐阜県観光公式サイト「岐阜の旅ガイド」をご覧ください。
https://www.kankou-gifu.jp/

#岐阜#観光#中津川#馬籠' where id = 'S2LCHR9sgbZzkk4u25m2-';
update content_bodies set title = 'Perfect G - Magome-juku Edition: With this, you too can be a Gifu enthusiast!', description = 'Gifu Prefecture is home to many tourist attractions, such as the UNESCO World Heritage site Shirakawa-go, Gero Onsen, Hida Takayama, and the cormorant fishing on the Nagara River, attracting a large number of visitors every year.
We want you to know more about Gifu Prefecture!
"Perfect G" uniquely highlights the charms of Gifu Prefecture.

Please take a look at the Magome-juku edition.

For tourist information about Gifu Prefecture, please visit the official Gifu Prefecture tourism site "Gifu Travel Guide."
https://www.kankou-gifu.jp/

