update content_bodies set title = '岐阜城パノラマ夜景プロモーションムービー', description = '斎藤道三公や織田信長公が居城としていた岐阜城を期間限定で夜間開館し、
天守閣から360度に広がる夜景を楽しむことができるイベント「岐阜城パノラマ夜景」。
プロモーションムービーではドローン撮影ならではの、通常見ることができない岐阜城や岐阜市の幻想的な夜景をご覧ください。

作成：岐阜市

※　※　※　※　※　※　※　※　※　※

公益財団法人岐阜観光コンベンション協会の【公式】YouTubeチャンネルです。

岐阜県岐阜市の観光やイベントの情報を発信し、みなさんに岐阜市の魅力をお届けします。
岐阜市にお住いの方、岐阜市に訪れる予定の方、旅行や観光が好きな方は、ぜひチャンネル登録をして岐阜市の情報をゲットしてください✨' where id = 'soRGgL19Aci6-5jVkxZRl';
update content_bodies set title = 'Gifu Castle Panorama Night View Promotion Movie', description = 'The event ''Gifu Castle Panorama Night View'' allows visitors to enjoy the night view from the main keep of Gifu Castle, which was the residence of Saito Dosan and Oda Nobunaga, during a limited-time night opening. In this promotional movie, experience the enchanting night views of Gifu Castle and Gifu City, captured through drone photography, which are usually not visible.

Produced by: Gifu City

※　※　※　※　※　※　※　※　※　※

This is the official YouTube channel of the Gifu Tourism and Convention Association.

We provide information about tourism and events in Gifu City, delivering the charm of Gifu City to everyone. If you live in Gifu City, plan to visit Gifu City, or love travel and tourism, please subscribe to our channel to get information about Gifu City! ✨' where id = 'WR1Fo2put5mdxN6GLj-7T';
update content_bodies set title = 'NISEKO SNOW DOME EXPERIENCE', description = '2024年12月下旬から2025年2月下旬にかけて、
雪の大型かまくらドームイベント「NISEKO SNOW DOME EXPERIENCE」を開催。
ニセコエリアの豪雪を活かした雪の大型かまくら多目的ドームを制作し、
かまくら内の天井部や壁部分を使って、
プロジェクションマッピングショーを行いました。
また、同会場では氷のグラスに入ったカクテルやソフトドリンクを提供するluxuryアイスバーを営業。


■倶知安観光協会公式SNS
【インスタグラム】
https://www.instagram.com/nisekokutchantravel/

■一般社団法人倶知安観光協会
 https://www.niseko.co.jp/

このチャンネルは、北海道ニセコエリアにある倶知安観光協会（くっちゃんかんこうきょうかい）が運営しています。 

