update content_bodies set title = 'NISEKO SNOW DOME EXPERIENCE', description = 'From late December 2024 to late February 2025,
the large snow igloo dome event "NISEKO SNOW DOME EXPERIENCE" will be held.
Utilizing the heavy snowfall in the Niseko area, we will create a large multi-purpose snow igloo dome,
and conduct a projection mapping show using the ceiling and wall sections inside the igloo.
Additionally, a luxury ice bar will be open at the venue, serving cocktails and soft drinks in ice glasses.

