update content_bodies set title = 'WELCOME BACK KUTCHAN NISEKO　【夏編】', description = '日本有数のリゾート地、北海道ニセコのおすすめスポットを紹介するチャンネルです！

■倶知安観光協会公式SNS
【インスタグラム】　
https://www.instagram.com/nisekokutchantravel/
【Twitter】
https://twitter.com/TravelNiseko_K

パンデミック前のニセコエリアは
毎年やってくる多くのリピーターで賑わっていました。

そしてついに今シーズン、インバウンド再開となりました。
多くの方に、再びこの地を訪れていただきたい。
ビデオのタイトルはその思いを込めて「WELCOME BACK」です！

観光客だけでなく、住民のみなさんにとっても安心安全が最重要と考え
「歓迎」「笑顔」「信頼感」「再生」「再会」を表現しています。

「WELCOME BACK！」「おかえりなさい！」
ここを訪れる方々を温かな心でお迎えします。

 #niseko #ニセコ #北海道 #倶知安#スキー#スノーボード#パウダースノー#powdersnow

このチャンネルは、北海道ニセコエリアにある倶知安観光協会（くっちゃんかんこうきょうかい）が運営しています。' where id = 'O3r-Ld7eZ1Wc_h7prrUgm';
update content_bodies set title = 'WELCOME BACK KUTCHAN NISEKO 【Summer Edition】', description = 'This is a channel that introduces recommended spots in Niseko, Hokkaido, one of Japan''s premier resort areas!

■ Kutchan Tourism Association Official SNS
【Instagram】  
https://www.instagram.com/nisekokutchantravel/  
【Twitter】  
https://twitter.com/TravelNiseko_K

Before the pandemic, the Niseko area was bustling with many repeat visitors every year.

And finally, this season, inbound tourism has resumed.
We hope many people will visit this place again.
The title of the video, "WELCOME BACK," reflects that sentiment!

We believe that safety and security are the top priorities not only for tourists but also for the residents,
expressing "welcome," "smiles," "trust," "revival," and "reunion."

"WELCOME BACK!" "Welcome home!"
We warmly welcome those who visit here.

#niseko #ニセコ #北海道 #倶知安 #スキー #スノーボード #パウダースノー #powdersnow

This channel is operated by the Kutchan Tourism Association located in the Niseko area of Hokkaido.' where id = 'sG79YfeBLXHrMbjXBgIFk';
