update content_bodies set title = '[Niseko Gourmet] Exquisite Breakfast Buffet at a Luxury Hotel! [Cloud Restaurant]', description = 'This is a channel introducing recommended spots in Niseko, Hokkaido, one of Japan''s premier resort areas!
This time, we will introduce the ''Cloud Restaurant'' located within ''Sky Niseko''!

It is a restaurant based on Japanese cuisine, focusing on fresh produce from Hokkaido!

During lunch, the menu includes hamburgers and croque monsieur!
For dinner, we offer a selection of share plate menus for you to enjoy with friends and family!

Due to COVID-19 measures, until October 31, we will switch from a full buffet style to a ''breakfast set'' style where you can choose from carefully handmade Japanese and Western dishes by the chef, depending on the number of guests.

